  assert_eq(semantic(generated), semantic(expected))
  // Renaming is part of the JOIN projection, not an extra materialization.
  assert_false(semantic(generated).contains("aql_chain_seed_"))
}

///|
test "JOIN chain preserves shared CTE capture and rejected resource ceilings" {
  let program = checked_with_join(
    "DATA joined = WITH seed AS (FROM orders |> SELECT id) SELECT l.id FROM seed AS l JOIN seed AS r ON l.id = r.id JOIN seed AS s ON r.id = s.id; FROM joined |> SELECT id",
    { ..fixture_context(), captured_stage: Some("capture"), },
  )
  assert_eq(@program.stage_count(program), 2)
  assert_eq(semantic(program).split("\"stage\":\"capture\"").length(), 2)
  let query = @query.parse_query(
    "SELECT l.x FROM t AS l CROSS JOIN t AS r CROSS JOIN t AS s",
    syntax_limits(),
  ).unwrap()
  assert_true(
    compile(query, join_order_context(), {
      ..construction_limits(),
      max_join_output_rows: 7L,
    })
    is Err(UnsupportedJoin),
  )
}

///|
test "JOIN chain DISTINCT reuses the selected expression after projection" {
  let program = checked_with_join(
    "DATA seed = FROM t |> SELECT x, y; SELECT DISTINCT l.x AS out FROM seed AS l JOIN seed AS m ON l.x = m.x JOIN seed AS r ON m.x = r.x ORDER BY l.x",
    join_order_context(),
  )
  assert_true(semantic(program).contains("\"field\":\"out\""))
  assert_true(
    compile_query_script(
      @query.parse_query_script(
        "DATA seed = FROM t |> SELECT x, y; SELECT DISTINCT l.x AS out FROM seed AS l JOIN seed AS m ON l.x = m.x JOIN seed AS r ON m.x = r.x ORDER BY r.y",
        syntax_limits(),
      ).unwrap(),
      join_order_context(),
      construction_limits(),
    )
    is Err(_),
  )
}

///|
test "JOIN chain filters original left columns before assigning private slots" {
  // The first WHERE runs before the JOIN projection creates private slots.
  // Independently declare its input and predicate, both JOIN ports and the
  // output-alias sort. Quoting range names must not change those bindings.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.pipe_slots","stages":[{"id":"aql_chain_source_0","inputs":{},"steps":[{"values":{"schema":{"x":{"type":"number","nullable":false},"y":{"type":"number","nullable":false}},"rows":[{"x":1,"y":20},{"x":2,"y":10}]},"as":"t"}],"results":{"aql_chain_source_0":{"from":"t","fields":["x","y"]}}},{"id":"main","inputs":{"aql_chain_input_0":{"result":{"stage":"aql_chain_source_0","result":"aql_chain_source_0"}},"aql_chain_input_1":{"result":{"stage":"aql_chain_source_0","result":"aql_chain_source_0"}},"aql_chain_input_2":{"result":{"stage":"aql_chain_source_0","result":"aql_chain_source_0"}}},"steps":[{"from":"aql_chain_input_0","filter":{"gt":[{"field":"x"},{"literal":1}]},"as":"aql_chain_filter_3"},{"from":"aql_chain_filter_3","join":{"with":"aql_chain_input_1","kind":"inner","on":[{"left":"x","right":"x"}],"max_output_rows":1000,"select":{"aql_chain_column_2":"left.x","aql_chain_column_3":"left.y","aql_chain_column_4":"right.x","aql_chain_column_5":"right.y"}},"as":"aql_chain_join_4"},{"from":"aql_chain_join_4","join":{"with":"aql_chain_input_2","kind":"inner","on":[{"left":"aql_chain_column_4","right":"x"}],"max_output_rows":1000,"select":{"aql_chain_column_2":"left.aql_chain_column_2","aql_chain_column_3":"left.aql_chain_column_3","aql_chain_column_4":"left.aql_chain_column_4","aql_chain_column_5":"left.aql_chain_column_5","aql_chain_column_6":"right.x","aql_chain_column_7":"right.y"}},"as":"aql_chain_join_5"},{"from":"aql_chain_join_5","derive":{"aql_pipe_sort_7":{"add":[{"field":"aql_chain_column_2"},{"literal":1}]}}},{"sort":[{"field":"aql_pipe_sort_7","dir":"asc","nulls":"first"}]},{"select":[{"y":"aql_chain_column_2"}],"as":"aql_chain_result_6"}],"results":{"rows":{"from":"aql_chain_result_6","fields":["y"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  for
    source in [
      "FROM t AS l |> WHERE l.x > 1 |> JOIN t AS r ON l.x = r.x |> JOIN t AS s ON r.x = s.x |> SELECT l.x AS y |> ORDER BY y + 1",
      "FROM t AS `l` |> WHERE `l`.`x` > 1 |> JOIN t AS `r` ON `l`.`x` = `r`.`x` |> JOIN t AS `s` ON `r`.`x` = `s`.`x` |> SELECT `l`.`x` AS y |> ORDER BY y + 1",
    ] {
    let generated = compile(
      @query.parse_query(source, syntax_limits()).unwrap(),
      join_order_context(),
      construction_limits(),
    ).unwrap()
    assert_eq(semantic(generated), semantic(expected))
    match
      @check.check_parsed(generated, check_environment(), None, check_limits()) {
      Checked(_) => ()
      Rejected(error) => raise @check.diagnostic_cause(error)
      _ => fail("filtered JOIN chain Values must be closed")
    }
  }
}

///|
test "projected Pipe JOIN agrees with an independent complete existing Program" {
  // One additional ordinary projection binds the left producer. Source-free
  // Values, both DATA producers, the cross join and Result remain shared IR.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_0"},{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_3"},{"from":"aql_script_seed_3","derive":{"aql_query_expr_0":{"literal":2}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_2"},{"from":"aql_data_0","select":["id"],"as":"aql_script_cte_5"},{"from":"aql_script_cte_5","cross_join":{"with":"aql_data_2","max_output_rows":10,"select":{"a":"left.id","b":"right.id"}},"as":"aql_join_output_7"},{"from":"aql_join_output_7","select":["a","b"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["a","b"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  match
    @check.check_parsed(expected, check_environment(), None, check_limits()) {
    Checked(_) => ()
    Rejected(error) => raise @check.diagnostic_cause(error)
    _ => fail("independent Values inputs are closed")
  }
  for
    body in [
      "FROM lefts |> SELECT id |> AS l |> CROSS JOIN rights AS r MAX_OUTPUT_ROWS 10 |> SELECT l.id AS a, r.id AS b",
      "SELECT id FROM lefts |> AS l |> CROSS JOIN rights AS r MAX_OUTPUT_ROWS 10 |> SELECT l.id AS a, r.id AS b",
      "FROM lefts AS old |> SELECT id |> AS discarded |> AS `L` |> CROSS JOIN rights AS r MAX_OUTPUT_ROWS 10 |> SELECT l.id AS a, r.id AS b",
    ] {
    let program = checked_with_join(
      "DATA lefts = SELECT 1 AS id; DATA rights = SELECT 2 AS id; DATA paired = " +
      body +
      "; FROM paired |> SELECT a, b",
      { ..fixture_context(), inputs: [], },
    )
    assert_eq(semantic(program), semantic(expected))
  }
}

///|
test "Pipe JOIN prefix keeps evaluated fields predicates limits and rebound ranges" {
  for
    text in [
      "FROM t AS old |> SELECT x + 10 AS id, y |> AS l |> WHERE l.id > 11 |> ORDER BY id |> LIMIT 1 |> JOIN r AS rr ON l.id = rr.k MAX_OUTPUT_ROWS 10 |> SELECT l.id, l.y, rr.k |> ORDER BY id",
      "FROM t AS old |> SELECT x AS id |> SET id = id + 1 |> AS l |> JOIN r AS rr ON l.id = rr.k MAX_OUTPUT_ROWS 10 |> SELECT l.id, rr.k",
      "FROM t AS old |> SELECT x AS id |> AS l |> SET id = id + 1 |> AS fresh |> JOIN r AS rr ON fresh.id = rr.k MAX_OUTPUT_ROWS 10 |> SELECT fresh.id, rr.k",
      "WITH base AS (SELECT x, y FROM t) FROM base AS old |> SELECT x AS id |> AS l |> JOIN r AS rr ON l.id = rr.k MAX_OUTPUT_ROWS 10 |> SELECT l.id, rr.k",
      "FROM t AS l |> JOIN r AS rr ON l.x = rr.k MAX_OUTPUT_ROWS 10 |> WHERE rr.k > 1 |> JOIN r AS s ON rr.k = s.k MAX_OUTPUT_ROWS 10 |> SELECT l.x",
    ] {
    for
      program in [
        match
          compile(
            @query.parse_query(text, syntax_limits()).unwrap(),
            join_order_context(),
            construction_limits(),
          ) {
          Ok(program) => program
          Err(UnsupportedCte) => fail("standalone UnsupportedCte: " + text)
          Err(UnsupportedJoin) => fail("standalone UnsupportedJoin: " + text)
          Err(Expression(_)) => fail("standalone Expression: " + text)
          Err(_) => fail("standalone: " + text)
        },
        match
          compile_query_script(
            @query.parse_query_script(text, syntax_limits()).unwrap(),
            join_order_context(),
            construction_limits(),
          ) {
          Ok(program) => program
          Err(UnsupportedCte) => fail("script UnsupportedCte: " + text)
          Err(UnsupportedJoin) => fail("script UnsupportedJoin: " + text)
          Err(Expression(_)) => fail("script Expression: " + text)
          Err(_) => fail("script: " + text)
        },
      ] {
      match
        @check.check_parsed(program, check_environment(), None, check_limits()) {
        Checked(_) => ()
        Rejected(error) => raise @check.diagnostic_cause(error)
        _ => fail("closed JOIN prefix must not introduce acquisition")
      }
      let wire = semantic(program)
      assert_true(wire.contains("\"max_output_rows\":10"))
      if text.contains("LIMIT 1") {
        assert_true(
          wire.contains("\"gt\":[{\"field\":\"id\"},{\"literal\":11}]"),
        )
        assert_true(wire.contains("\"take\":{\"count\":1,\"offset\":0}"))
        assert_eq(wire.split("\"add\":").length(), 2)
      }
    }
  }
}

///|
test "projected Pipe JOIN cannot revive removed columns or displaced aliases" {
  for
    text in [
      "FROM t AS old |> SELECT x AS id |> AS l |> JOIN r AS rr ON old.x = rr.k |> SELECT l.id",
      "FROM t AS old |> SELECT x AS id |> AS l |> JOIN r AS rr ON l.y = rr.k |> SELECT l.id",
      "FROM t |> SELECT x AS id |> AS old |> AS l |> JOIN r AS rr ON old.id = rr.k |> SELECT l.id",
      "FROM t |> SELECT x AS id |> AS l |> JOIN r AS l ON l.id = l.k |> SELECT id",
    ] {
    let result = compile(
      @query.parse_query(text, syntax_limits()).unwrap(),
      join_order_context(),
      construction_limits(),
    )
    if text.contains("AS l ON") {
      assert_true(result is Err(AmbiguousRelation), msg=text)
    } else {
      assert_true(result is Err(AmbiguousColumn), msg=text)
    }
  }
}

///|
test "Pipe JOIN preserves SET DROP and RENAME range snapshots through the checker" {
  for
    (prefix, projection) in [
      ("SET x = x + 10", "x AS current, l.x AS original, rr.k AS matched"),
      ("DROP x", "y AS current, l.x AS original, rr.k AS matched"),
      ("RENAME x AS current", "current, l.x AS original, rr.k AS matched"),
    ] {
    let text = "FROM t |> AS l |> " +
      prefix +
      " |> JOIN r AS rr ON l.x = rr.k MAX_OUTPUT_ROWS 10 |> SELECT " +
      projection +
      " |> ORDER BY original"
    let query = @query.parse_query(text, syntax_limits()).unwrap()
    for
      program in [
        compile(query, join_order_context(), construction_limits()).unwrap(),
        compile_query_script(
          @query.single_query_script(query),
          join_order_context(),
          construction_limits(),
        ).unwrap(),
      ] {
      match
        @check.check_parsed(program, check_environment(), None, check_limits()) {
        Checked(_) => ()
        Rejected(error) => raise @check.diagnostic_cause(error)
        _ => fail("closed range snapshots must not introduce acquisition")
      }
    }
  }
}

///|
test "Pipe JOIN remaps evaluated slots rather than rebinding original values" {
  // Full independent existing Program: SET derives another slot, ON uses x,
  // and the output carries both that original and the evaluated replacement.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1},"aql_query_expr_1":{"literal":10}}},{"select":[{"x":"aql_query_expr_0"},{"y":"aql_query_expr_1"}],"as":"aql_data_0"},{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_3"},{"from":"aql_script_seed_3","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"k":"aql_query_expr_0"}],"as":"aql_data_2"},{"from":"aql_data_0","derive":{"aql_pipe_set_2":{"add":[{"field":"x"},{"literal":10}]}},"as":"aql_script_cte_5"},{"from":"aql_script_cte_5","join":{"with":"aql_data_2","max_output_rows":10,"select":{"aql_chain_column_3":"left.x","aql_chain_column_4":"left.y","aql_chain_column_5":"left.aql_pipe_set_2","aql_chain_column_6":"right.k"},"kind":"inner","on":[{"left":"x","right":"k"}]},"as":"aql_chain_join_6"},{"from":"aql_chain_join_6","select":[{"current":"aql_chain_column_5"},{"original":"aql_chain_column_3"},{"matched":"aql_chain_column_6"}],"as":"aql_chain_result_7"},{"from":"aql_chain_result_7","select":["current","original","matched"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["current","original","matched"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  let actual = checked_with_join(
    "DATA lefts = SELECT 1 AS x, 10 AS y; DATA rights = SELECT 1 AS k; DATA paired = FROM lefts |> AS l |> SET x = x + 10 |> JOIN rights AS rr ON l.x = rr.k MAX_OUTPUT_ROWS 10 |> SELECT x AS current, l.x AS original, rr.k AS matched; FROM paired |> SELECT current, original, matched",
    { ..fixture_context(), inputs: [], },
  )
  assert_eq(semantic(actual), semantic(expected))
}

///|
test "Pipe JOIN carries several ranges and refuses removed current names" {
  let query = @query.parse_query(
    "FROM t AS l |> JOIN r AS rr ON l.x = rr.k MAX_OUTPUT_ROWS 10 |> SET x = x + 10 |> JOIN r AS s ON l.x = s.k MAX_OUTPUT_ROWS 10 |> SELECT x AS current, l.x AS original, rr.k AS first, s.k AS second",
    syntax_limits(),
  ).unwrap()
  let program = compile(query, join_order_context(), construction_limits()).unwrap()
  match
    @check.check_parsed(program, check_environment(), None, check_limits()) {
    Checked(_) => ()
    Rejected(error) => raise @check.diagnostic_cause(error)
    _ => fail("range continuation remains closed")
  }
  for prefix in ["DROP x", "RENAME x AS current"] {
    assert_true(
      compile(
        @query.parse_query(
          "FROM t |> AS l |> " +
          prefix +
          " |> JOIN r AS rr ON x = rr.k |> SELECT l.x",
          syntax_limits(),
        ).unwrap(),
        join_order_context(),
        construction_limits(),
      )
      is Err(AmbiguousColumn),
    )
  }
}
